function notify(message,error=false){noticePayload={message,error};const copy=typeof message==='object'?message[locale]:t(message);$('notice').innerHTML=`<div class="notice${error?' error':''}">${rawEscape(copy)}</div>`;}
function persist(){if(protectExisting)return;storageError=saveState(storage,state);renderStorage();}
function renderStorage(){
  $('storage-status').innerHTML=storageError?t(`<div class="storage-alert"><strong>Lưu trữ cần xử lý</strong><br>${rawEscape(t(storageError))}<div class="actions"><button id="retry-storage" class="secondary">Thử đọc lại dữ liệu lưu</button>${protectExisting?'<button id="replace-storage" class="secondary">Dùng và lưu bộ mẫu tạm hiện tại</button>':''}<button id="emergency-backup" class="secondary">Xuất dữ liệu đang có</button></div></div>`):'';
  $('retry-storage')?.addEventListener('click',()=>{if(!protectExisting&&!confirmLocal('Đọc lại bản đã lưu có thể thay bài làm chưa lưu trong bộ nhớ. Hãy xuất backup trước. Tiếp tục?'))return;const retry=loadState(storage);if(retry.error){storageError=retry.error;renderStorage();}else{state=retry.state;storageError=null;protectExisting=false;renderStorage();render();notify('Đã đọc lại dữ liệu lưu.');}});
  $('replace-storage')?.addEventListener('click',()=>{if(confirmLocal('Ghi bộ mẫu tạm hiện tại thay dữ liệu lưu không đọc được? Hãy giữ backup trước khi tiếp tục.')){protectExisting=false;persist();notify(storageError||'Đã lưu bộ mẫu tạm.',!!storageError);}});
  $('emergency-backup')?.addEventListener('click',()=>downloadBackup());
}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove();},60000);}
function openExport(title,filename,content,type){exportPayload={filename,content,type};$('export-content-label').textContent=bilingual('Nội dung xuất · chỉ đọc','Export contents · read only');$('export-title').textContent=t(title);$('export-description').textContent=locale==='en'?`File: ${filename}. If a download is unavailable, copy all contents and save a ${type.includes('json')?'JSON':'text'} file on your device.`:`File: ${filename}. Nếu trình duyệt không tải được, sao chép toàn bộ nội dung và lưu thành file ${type.includes('json')?'JSON':'text'} trên máy.`;$('export-content').value=content;$('export-feedback').textContent=t('Nội dung đã sẵn sàng. Chưa xác nhận file được lưu trên máy.');$('export-dialog').showModal();}
