function sourceEditor(card={title:'',text:''}){return `<div class="source-editor-row"><div class="field"><label>Tên thẻ nguồn<input name="source-title" value="${escape(card.title)}" maxlength="200"></label></div><div class="field"><label>Nội dung nguồn / tình huống<textarea name="source-text" maxlength="4000">${escape(card.text)}</textarea></label></div><button type="button" class="quiet-button remove-source">Bỏ thẻ này</button></div>`;}
